import type { Mode } from '../app/state'
import type { ChatMessage, GemmaEvent, GemmaRequest } from './protocol'

export type GemmaReply = { text: string; ms: number; tokens: number; stopped: boolean }

type Pending = {
  resolve: (reply: GemmaReply) => void
  reject: (error: Error) => void
  onToken?: (text: string) => void
}

// Page-side handle on the Gemma worker. One reply at a time: the interview
// never asks for two, and a new request stops the one before it.
export class GemmaClient {
  private worker: Worker
  private nextId = 1
  private pending = new Map<number, Pending>()
  private loadWaiters: { resolve: (r: { loadMs: number; warmMs: number }) => void; reject: (e: Error) => void }[] = []
  private onProgress?: (file: string, loaded: number, total: number) => void

  constructor() {
    this.worker = new Worker(new URL('./gemma.worker.ts', import.meta.url), { type: 'module' })
    this.worker.onmessage = (e: MessageEvent<GemmaEvent>) => this.handle(e.data)
    this.worker.onerror = (e) => this.failAll(new Error(e.message || 'Gemma worker crashed'))
  }

  load(mode: Mode, onProgress?: (file: string, loaded: number, total: number) => void) {
    this.onProgress = onProgress
    const done = new Promise<{ loadMs: number; warmMs: number }>((resolve, reject) =>
      this.loadWaiters.push({ resolve, reject }),
    )
    this.send({ type: 'load', mode })
    return done
  }

  generate(messages: ChatMessage[], opts: { maxNewTokens: number; onToken?: (text: string) => void }) {
    if (this.pending.size) this.stop()
    const id = this.nextId++
    return new Promise<GemmaReply>((resolve, reject) => {
      this.pending.set(id, { resolve, reject, onToken: opts.onToken })
      this.send({ type: 'generate', id, messages, maxNewTokens: opts.maxNewTokens })
    })
  }

  stop() {
    this.send({ type: 'stop' })
  }

  dispose() {
    this.worker.terminate()
    this.failAll(new Error('Gemma worker stopped'))
  }

  private send(req: GemmaRequest) {
    this.worker.postMessage(req)
  }

  private handle(ev: GemmaEvent) {
    switch (ev.type) {
      case 'progress':
        this.onProgress?.(ev.file, ev.loaded, ev.total)
        break
      case 'ready':
        this.loadWaiters.splice(0).forEach((w) => w.resolve({ loadMs: ev.loadMs, warmMs: ev.warmMs }))
        break
      case 'token':
        this.pending.get(ev.id)?.onToken?.(ev.text)
        break
      case 'result': {
        const p = this.pending.get(ev.id)
        this.pending.delete(ev.id)
        p?.resolve({ text: ev.text, ms: ev.ms, tokens: ev.tokens, stopped: ev.stopped })
        break
      }
      case 'error': {
        const error = new Error(ev.message)
        if (ev.stage === 'load') this.loadWaiters.splice(0).forEach((w) => w.reject(error))
        else if (ev.id !== undefined) {
          this.pending.get(ev.id)?.reject(error)
          this.pending.delete(ev.id)
        }
        break
      }
    }
  }

  private failAll(error: Error) {
    this.loadWaiters.splice(0).forEach((w) => w.reject(error))
    this.pending.forEach((p) => p.reject(error))
    this.pending.clear()
  }
}

import { useEffect, useRef, useState } from 'react'
import type { Mode } from '../app/state'
import { GemmaClient, type GemmaReply } from '../gemma/GemmaClient'

// Dev only (`?dev=gemma`), never in the production build: checks the Gemma
// worker on its own. Loading downloads the model (no cache until step 1.4).
export default function GemmaTest() {
  const client = useRef<GemmaClient | null>(null)
  const files = useRef(new Map<string, { loaded: number; total: number }>())
  const [mode, setMode] = useState<Mode>('light')
  const [status, setStatus] = useState('not loaded')
  const [prompt, setPrompt] = useState('Ask me one interview question for a junior frontend developer.')
  const [streamed, setStreamed] = useState('')
  const [reply, setReply] = useState<GemmaReply | null>(null)

  useEffect(() => () => client.current?.dispose(), [])

  async function load() {
    client.current?.dispose()
    client.current = new GemmaClient()
    files.current.clear()
    setStatus('loading')
    try {
      const r = await client.current.load(mode, (file, loaded, total) => {
        files.current.set(file, { loaded, total })
        let l = 0
        let t = 0
        files.current.forEach((f) => ((l += f.loaded), (t += f.total)))
        setStatus(`downloading ${(l / 1e6).toFixed(0)} / ${(t / 1e6).toFixed(0)} MB`)
      })
      setStatus(`ready: load ${(r.loadMs / 1000).toFixed(1)} s, warm-up ${r.warmMs} ms`)
    } catch (e) {
      setStatus(`load failed: ${e instanceof Error ? e.message : e}`)
    }
  }

  async function generate() {
    if (!client.current) return
    setStreamed('')
    setReply(null)
    try {
      const r = await client.current.generate([{ role: 'user', content: prompt }], {
        maxNewTokens: 80,
        onToken: (t) => setStreamed((s) => s + t),
      })
      setReply(r)
    } catch (e) {
      setStatus(`generate failed: ${e instanceof Error ? e.message : e}`)
    }
  }

  return (
    <section className="screen glass">
      <h1>Gemma worker test</h1>
      <p className="muted">Dev only. Loading downloads the model.</p>
      <div className="actions" style={{ justifyContent: 'flex-start' }}>
        <select value={mode} onChange={(e) => setMode(e.target.value as Mode)} aria-label="Mode">
          <option value="light">Light (Gemma 3 1B)</option>
          <option value="heavy">Heavy (Gemma 4 E2B)</option>
        </select>
        <button type="button" onClick={load}>
          Load
        </button>
      </div>
      <p id="gemma-status" role="status">
        {status}
      </p>
      <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} rows={3} style={{ width: '100%' }} />
      <div className="actions" style={{ justifyContent: 'flex-start' }}>
        <button type="button" className="primary" onClick={generate}>
          Generate
        </button>
        <button type="button" onClick={() => client.current?.stop()}>
          Stop
        </button>
      </div>
      <p id="gemma-stream">{streamed}</p>
      {reply && (
        <p id="gemma-reply" className="muted">
          {reply.ms} ms, {reply.tokens} tokens{reply.stopped ? ', stopped' : ''}
        </p>
      )}
    </section>
  )
}

