import { createModelCache, isModelCacheSupported } from 'react-ai-voice-avatar/model-cache'
import type { Display, Mode } from '../app/state'
import { GEMMA_MODELS } from '../gemma/protocol'

// Loading progress for the setup screen (UX.md: downloads). One row per model
// that reports real progress: Whisper and Kokoro (from the package), the
// mode's Gemma (from our worker), and the avatar for a video interview. The
// voice detector and the ONNX runtime are small, load from jsDelivr and report
// no progress, so the setup screen mentions them without a bar.

export type LoadItemId = 'whisper' | 'kokoro' | 'gemma' | 'avatar'

export type LoadPhase = 'waiting' | 'downloading' | 'from-device' | 'ready' | 'failed'

export type LoadItem = { pct: number; phase: LoadPhase; cached: boolean; message?: string }

export type LoadState = Partial<Record<LoadItemId, LoadItem>>

export type LoadAction =
  | { type: 'reset'; items: LoadItemId[] }
  | { type: 'cached'; id: LoadItemId; cached: boolean }
  | { type: 'progress'; id: LoadItemId; pct: number }
  | { type: 'ready'; id: LoadItemId }
  | { type: 'failed'; id: LoadItemId; message: string }

export function itemsFor(display: Display): LoadItemId[] {
  return display === 'video' ? ['whisper', 'kokoro', 'gemma', 'avatar'] : ['whisper', 'kokoro', 'gemma']
}

export function loadReducer(state: LoadState, action: LoadAction): LoadState {
  if (action.type === 'reset') {
    return Object.fromEntries(
      action.items.map((id) => [id, { pct: 0, phase: 'waiting', cached: false } satisfies LoadItem]),
    )
  }
  const item = state[action.id]
  if (!item || item.phase === 'ready' || item.phase === 'failed') return state
  switch (action.type) {
    case 'cached':
      return { ...state, [action.id]: { ...item, cached: action.cached } }
    case 'progress': {
      // Progress is reported for cache reads too, so the phase comes from
      // whether the files were already on this device, not from the event.
      const pct = Math.max(item.pct, Math.min(100, action.pct))
      return { ...state, [action.id]: { ...item, pct, phase: item.cached ? 'from-device' : 'downloading' } }
    }
    case 'ready':
      return { ...state, [action.id]: { ...item, pct: 100, phase: 'ready' } }
    case 'failed':
      return { ...state, [action.id]: { ...item, phase: 'failed', message: action.message } }
  }
}

export function allReady(state: LoadState): boolean {
  const items = Object.values(state)
  return items.length > 0 && items.every((i) => i.phase === 'ready')
}

// The weight files that decide whether a model is already on this device. Keys
// are the Hugging Face URLs transformers.js asks the cache for; the package and
// our Gemma worker share one OPFS store.
const HF = 'https://huggingface.co/'
const KEY_FILES: Record<Exclude<LoadItemId, 'avatar'>, (mode: Mode) => string[]> = {
  whisper: () => [
    `${HF}onnx-community/whisper-base/resolve/main/onnx/encoder_model.onnx`,
    `${HF}onnx-community/whisper-base/resolve/main/onnx/decoder_model_merged.onnx`,
  ],
  kokoro: () => [`${HF}onnx-community/Kokoro-82M-v1.0-ONNX/resolve/main/onnx/model.onnx`],
  gemma: (mode) => {
    const { id, dtype } = GEMMA_MODELS[mode]
    return mode === 'heavy'
      ? [
          `${HF}${id}/resolve/main/onnx/embed_tokens_${dtype}.onnx_data`,
          `${HF}${id}/resolve/main/onnx/decoder_model_merged_${dtype}.onnx_data`,
        ]
      : [`${HF}${id}/resolve/main/onnx/model_${dtype}.onnx_data`]
  },
}

export async function isOnDevice(id: Exclude<LoadItemId, 'avatar'>, mode: Mode): Promise<boolean> {
  if (!isModelCacheSupported()) return false
  const cache = createModelCache()
  try {
    const hits = await Promise.all(KEY_FILES[id](mode).map((url) => cache.match(url)))
    return hits.every(Boolean)
  } catch {
    return false
  }
}

import { lazy, Suspense, useEffect, useRef, type Dispatch } from 'react'
import type { Display, Mode } from '../app/state'
import { GemmaClient } from '../gemma/GemmaClient'
import { isOnDevice, itemsFor, type LoadAction } from './loading'
import { PhoneEngine } from './PhoneEngine'

// Only fetched when the candidate picks the video interview, so three.js and
// the avatar never load for a phone screen.
const VideoEngine = lazy(() => import('./VideoEngine'))

// The one place the models live. App mounts this once, at a fixed spot in its
// tree, from the display choice on the setup screen until the interview ends;
// it is hidden on setup (loading in the background) and shown as the stage on
// the interview screen. It owns the app's Gemma worker; the voice engine (the
// package's hook, or <AiVoiceAvatar> for video) runs inside the child.
export function EngineHost({
  display,
  mode,
  visible,
  onLoad,
}: {
  display: Display
  mode: Mode
  visible: boolean
  onLoad: Dispatch<LoadAction>
}) {
  const gemma = useRef<GemmaClient | null>(null)

  useEffect(() => {
    onLoad({ type: 'reset', items: itemsFor(display) })
    for (const id of ['whisper', 'kokoro', 'gemma'] as const) {
      void isOnDevice(id, mode).then((cached) => onLoad({ type: 'cached', id, cached }))
    }
  }, [display, mode, onLoad])

  useEffect(() => {
    const client = new GemmaClient()
    gemma.current = client
    const files = new Map<string, { loaded: number; total: number }>()
    client
      .load(mode, (file, loaded, total) => {
        files.set(file, { loaded, total })
        let l = 0
        let t = 0
        files.forEach((f) => {
          l += f.loaded
          t += f.total
        })
        if (t > 0) onLoad({ type: 'progress', id: 'gemma', pct: (l / t) * 100 })
      })
      .then(() => onLoad({ type: 'ready', id: 'gemma' }))
      .catch((e: Error) => {
        // dispose() during unmount rejects too; that is not a failure to show.
        if (gemma.current === client) onLoad({ type: 'failed', id: 'gemma', message: e.message })
      })
    return () => {
      gemma.current = null
      client.dispose()
    }
  }, [mode, onLoad])

  return (
    <div className="engine-host" hidden={!visible}>
      {display === 'video' ? (
        <Suspense fallback={<div className="stage stage-video" aria-hidden="true" />}>
          <VideoEngine mode={mode} />
        </Suspense>
      ) : (
        <PhoneEngine onLoad={onLoad} />
      )}
    </div>
  )
}

import { useEffect, type Dispatch } from 'react'
import { useAiVoiceAvatar } from 'react-ai-voice-avatar/headless'
import type { LoadAction, LoadItemId } from './loading'

// The package's progress labels for the models we show.
const LABELS: Record<string, LoadItemId> = { asr: 'whisper', kokoro: 'kokoro' }

// Phone screen: the package's headless hook runs hearing and voice, no
// three.js. `onSubmit` is supplied, so the package never downloads its own
// language model; replies come from the app's Gemma (step 3.x). Listening is
// not started here: the microphone is only opened after the mic check explains
// why (step 2.4).
export function PhoneEngine({ onLoad }: { onLoad: Dispatch<LoadAction> }) {
  const voice = useAiVoiceAvatar({
    ttsEngine: 'kokoro',
    // An empty reply means "say nothing, keep listening" (package 0.7.0).
    onSubmit: () => '',
    loadingProgress: (pct, label) => {
      const id = LABELS[label]
      if (id) onLoad({ type: 'progress', id, pct })
    },
    onError: (e) => {
      if (e.severity !== 'fatal') return
      if (e.stage === 'speech-recognition') onLoad({ type: 'failed', id: 'whisper', message: e.message })
      else if (e.stage === 'speech-synthesis') onLoad({ type: 'failed', id: 'kokoro', message: e.message })
    },
  })

  // The hook leaves 'loading' once hearing and voice are both up.
  const loaded = voice.status !== 'loading'
  useEffect(() => {
    if (!loaded) return
    onLoad({ type: 'ready', id: 'whisper' })
    onLoad({ type: 'ready', id: 'kokoro' })
  }, [loaded, onLoad])

  return (
    <div className="stage stage-phone" aria-hidden="true">
      <p className="placeholder">Voice only</p>
    </div>
  )
}

