import { useEffect, type Dispatch } from 'react'
import { useAiVoiceAvatar } from 'react-ai-voice-avatar/headless'
import type { LoadAction, LoadItemId } from './loading'
import { registerVoiceControls, setVoice } from './voiceStore'
import { onTranscript, type EngineProps } from './engineEvents'

// The package's progress labels for the models we show.
const LABELS: Record<string, LoadItemId> = { asr: 'whisper', kokoro: 'kokoro' }

// Phone screen: the package's headless hook runs hearing and voice, no
// three.js. `onSubmit` is supplied, so the package never downloads its own
// language model; replies come from the app's Gemma through EngineHost.
// Listening starts from the Start interview press (a user gesture), after the
// setup screen has said why the microphone is needed.
export function PhoneEngine({ onLoad, onSubmit, onInterrupt }: EngineProps & { onLoad: Dispatch<LoadAction> }) {
  const voice = useAiVoiceAvatar({
    ttsEngine: 'kokoro',
    ttsVoice: 'af_heart',
    onSubmit,
    onUserInterrupt: onInterrupt,
    onTranscriptUpdate: onTranscript,
    loadingProgress: (pct, label) => {
      const id = LABELS[label]
      if (id) onLoad({ type: 'progress', id, pct })
    },
    onError: (e) => {
      if (e.stage === 'microphone') setVoice({ micError: e.message })
      if (e.severity !== 'fatal') return
      if (e.stage === 'speech-recognition') onLoad({ type: 'failed', id: 'whisper', message: e.message })
      else if (e.stage === 'speech-synthesis') onLoad({ type: 'failed', id: 'kokoro', message: e.message })
    },
  })

  // The hook leaves 'loading' once hearing and voice are both up.
  const loaded = voice.status !== 'loading'
  useEffect(() => {
    if (!loaded) return
    onLoad({ type: 'ready', id: 'whisper' })
    onLoad({ type: 'ready', id: 'kokoro' })
  }, [loaded, onLoad])

  useEffect(() => {
    setVoice({ status: voice.status, micError: voice.micError })
  }, [voice.status, voice.micError])

  const { startListening, stopListening, interrupt, speak } = voice
  useEffect(() => {
    registerVoiceControls({ startListening, stopListening, interrupt, speak })
    return () => registerVoiceControls(null)
  }, [startListening, stopListening, interrupt, speak])

  return (
    <div className="stage stage-phone" aria-hidden="true">
      <p className="placeholder">Voice only</p>
    </div>
  )
}

import { setVoice } from './voiceStore'

// What EngineHost hands each engine: the same for phone and video.
export type EngineProps = {
  onSubmit: (text: string) => AsyncIterable<string> | string
  onInterrupt: () => void
}

let saidThisTurn = ''

// Captions for both engines. The package reports what Whisper heard once per
// stretch of speech, and what the interviewer says a sentence at a time.
export function onTranscript(text: string, speaker: 'user' | 'avatar') {
  if (speaker === 'user') {
    saidThisTurn = ''
    setVoice({ heard: text })
  } else {
    saidThisTurn = saidThisTurn ? `${saidThisTurn} ${text}` : text
    setVoice({ said: saidThisTurn })
  }
}

import { Canvas } from '@react-three/fiber'
import { useCallback, useEffect, useRef, type Dispatch } from 'react'
import { AiVoiceAvatar, type AiVoiceAvatarHandle } from 'react-ai-voice-avatar'
import { usePrefersReducedMotion } from '../app/usePrefersReducedMotion'
import { onTranscript, type EngineProps } from './engineEvents'
import type { LoadAction, LoadItemId } from './loading'
import { registerVoiceControls, setVoice } from './voiceStore'

const LABELS: Record<string, LoadItemId> = { asr: 'whisper', kokoro: 'kokoro' }

// Video interview: <AiVoiceAvatar> runs hearing, voice and lip sync and draws
// the avatar. It runs its own copy of the package's hook, so it gets the same
// config as PhoneEngine (TASKS.md: the Video vs Phone workaround). Default
// export for React.lazy, so three.js only loads for a video interview.
// The app draws its own state, question and captions, so the package's pill
// and captions are off. Reduced motion: no gestures (lip sync stays).
export default function VideoEngine({
  onLoad,
  visible,
  onSubmit,
  onInterrupt,
}: EngineProps & { onLoad: Dispatch<LoadAction>; visible: boolean }) {
  const reducedMotion = usePrefersReducedMotion()
  const avatar = useRef<AiVoiceAvatarHandle>(null)

  // The handle's methods are read at call time, so the controls stay valid
  // whatever the avatar re-renders.
  useEffect(() => {
    registerVoiceControls({
      startListening: () => avatar.current?.startListening() ?? Promise.resolve(),
      stopListening: () => avatar.current?.stopListening(),
      interrupt: () => avatar.current?.interrupt(),
      speak: (text) => avatar.current?.speak(text),
    })
    return () => registerVoiceControls(null)
  }, [])

  const loadingProgress = useCallback(
    (value: number, label: string) => {
      // The avatar reports a fraction (0-1); the models report percent.
      if (label.startsWith('avatar-')) onLoad({ type: 'progress', id: 'avatar', pct: value * 100 })
      else if (LABELS[label]) onLoad({ type: 'progress', id: LABELS[label], pct: value })
    },
    [onLoad],
  )

  return (
    <div className="stage stage-video">
      {/* No frames drawn while off stage on the setup screen: the GPU is busy
          loading the models. */}
      <Canvas
        camera={{ position: [0, 0.15, 2.2], fov: 32 }}
        frameloop={visible ? 'always' : 'demand'}
        aria-hidden="true"
      >
        <AiVoiceAvatar
          ref={avatar}
          avatarPreset="ananya"
          lightingPreset="studio"
          ttsEngine="kokoro"
          ttsVoice="af_heart"
          onSubmit={onSubmit}
          onUserInterrupt={onInterrupt}
          onTranscriptUpdate={onTranscript}
          hideStatusPill
          showCaptions={false}
          gestures={!reducedMotion}
          loadingProgress={loadingProgress}
          onModelLoaded={() => onLoad({ type: 'ready', id: 'avatar' })}
          onStatusChange={(status) => {
            setVoice({ status })
            if (status === 'loading') return
            onLoad({ type: 'ready', id: 'whisper' })
            onLoad({ type: 'ready', id: 'kokoro' })
          }}
          onError={(e) => {
            if (e.stage === 'microphone') setVoice({ micError: e.message })
            if (e.severity !== 'fatal') return
            if (e.stage === 'speech-recognition') onLoad({ type: 'failed', id: 'whisper', message: e.message })
            else if (e.stage === 'speech-synthesis') onLoad({ type: 'failed', id: 'kokoro', message: e.message })
          }}
        />
      </Canvas>
    </div>
  )
}

import { useEffect } from 'react'
import type { Display } from '../app/state'
import { ScreenFrame } from '../components/ScreenFrame'
import { useVoice, voiceControls, type VoiceStatus } from '../engine/voiceStore'
import { OPENING } from '../interview/placeholderBrain'

// One clear state, in words (UX.md: interview screen). 'idle' means the mic is
// open and waiting for speech, which to the candidate is listening too.
const STATE_LABEL: Record<VoiceStatus, string> = {
  loading: 'Getting ready',
  idle: 'Listening',
  listening: 'Listening',
  thinking: 'Thinking',
  speaking: 'Speaking',
}

// Step 2.1 wiring: the voice loop end to end with a placeholder interviewer.
// Phase 3 (engine) and step 4.2 (room layout, timer, controls) build on it.
// The avatar or voice-only stage is not here: it belongs to the engine, which
// App keeps mounted beside this screen.
export function Interview({ display, onEnd }: { display: Display; onEnd: () => void }) {
  const voice = useVoice()

  useEffect(() => {
    voiceControls()?.speak(OPENING)
  }, [])

  return (
    <ScreenFrame title={display === 'video' ? 'Video interview' : 'Phone screen'}>
      <p className="state" role="status">
        {STATE_LABEL[voice.status]}
      </p>

      {voice.micError && (
        <div className="notice">
          <p className="notice-title">The microphone isn't available</p>
          <p>
            Allow microphone access for this page (the icon in the address bar), check that a
            microphone is connected, then reload. ({voice.micError})
          </p>
        </div>
      )}

      <section aria-labelledby="question-title">
        <h2 id="question-title" className="label">
          Interviewer
        </h2>
        <p className="question">{voice.said || OPENING}</p>
      </section>

      <section aria-labelledby="heard-title">
        <h2 id="heard-title" className="label">
          What I heard
        </h2>
        <p className={voice.heard ? 'heard' : 'heard placeholder'} aria-live="polite">
          {voice.heard || 'Your words appear here once you finish a sentence.'}
        </p>
      </section>

      <div className="actions interview-controls">
        <button type="button" className="primary">
          I'm done
        </button>
        <button type="button">Repeat question</button>
        <button type="button">Skip</button>
        <button
          type="button"
