// What every Gemma line goes through before it is spoken (PLAN.md section 4).
// Ported from evals/interviewer.html with the two fixes run 5 showed: a
// question may end in "." or be an instruction ("Describe…"), and a reaction
// that is really a new question is rejected. Returns null when nothing usable
// survives, and the caller speaks a written line instead.

const PRAISE =
  /good start|good example|great answer|great question|excellent|amazing|impressive|well done|nice work|that's great|that is great|let.s start/i

// Openings that make a sentence a question or a request to answer.
const ASKS =
  /^(what|how|why|when|where|which|who|whose|can|could|would|will|do|did|does|is|are|was|were|have|has|tell me|walk me|talk me|describe|explain|give me|share)\b/i

const norm = (s: string) => s.toLowerCase().replace(/[^a-z ]/g, '').replace(/\s+/g, ' ').trim()

function sentences(text: string): string[] {
  const t = text.replace(/[“”"*_#[\]`]/g, '').replace(/\s+/g, ' ').trim()
  return (t.match(/[^.!?]+[.!?]+|[^.!?]+$/g) ?? []).map((s) => s.trim()).filter(Boolean)
}

const isAsk = (s: string) => s.endsWith('?') || ASKS.test(s)

// The model speaking as the candidate ("Rahul: I'm seeking…") or narrating
// ("He explained the steps…") rather than asking.
const ROLE_PLAY = /^[A-Z][a-z]+:|^(he|she|they) (explained|said|described|answered)\b/

export function guardFollowUp(raw: string, asked = '', answer = ''): string | null {
  if (ROLE_PLAY.test(raw.trim())) return null
  const answerNorm = norm(answer)
  const ss = sentences(raw)
    .filter((s) => !PRAISE.test(s))
    .filter((s) => norm(s) !== norm(asked) && !(answer && norm(s).length > 12 && answerNorm.includes(norm(s))))
  const qi = ss.findIndex(isAsk)
  if (qi === -1) return null
  // A question word ending in "." becomes a spoken question.
  let question = ss[qi]
  if (question.endsWith('.') && !/^(tell me|walk me|talk me|describe|explain|give me|share)\b/i.test(question)) {
    question = `${question.slice(0, -1)}?`
  }
  // Keep at most one short lead-in sentence before the question.
  const lead = qi > 0 && !isAsk(ss[qi - 1]) ? `${ss[qi - 1]} ` : ''
  const line = `${lead}${question}`
  return line.split(/\s+/).length > 40 ? question : line
}

export function guardReaction(raw: string): string | null {
  if (ROLE_PLAY.test(raw.trim())) return null
  const ss = sentences(raw).filter((s) => !PRAISE.test(s) && !isAsk(s))
  return ss[0] ?? null
}

import type { ChatMessage } from '../gemma/protocol'
import type { Level, Track } from './bank'
import type { Mood } from './lines'

// The guided follow-up prompt from evals/interviewer.html (run 3, the version
// that gave 8 of 12 usable lines on Gemma 3 1B and 12 of 12 on-angle lines on
// Gemma 4 E2B). The conversation is passed as real turns, so the model writes
// the interviewer's next turn instead of re-enacting a transcript; the angle
// rides along as a note on the candidate's turn. Gemma 3 has no system role,
// so the persona goes on the first user turn, which works for both models.

const MOODS: Record<Mood, string> = {
  friendly: 'Your manner: warm and encouraging. You may start with a few words that echo something specific they said.',
  neutral: 'Your manner: calm and professional. You may start with "Okay." or "Got it." and nothing more.',
  tough: 'Your manner: direct and sceptical, like a demanding hiring manager. No praise, no softening. Get straight to the question.',
}

const TRACK_ROLE: Record<Track, string> = {
  frontend: 'frontend developer',
  backend: 'backend developer',
  ml: 'machine learning engineer',
}

export type PersonaOptions = { interviewer: string; mood: Mood; track: Track; level: Level; candidateName?: string }

export function persona(o: PersonaOptions): string {
  const who = o.candidateName ?? 'the candidate'
  return `You are ${o.interviewer}, a senior engineer interviewing ${who} for a ${o.level} ${TRACK_ROLE[o.track]} role. This is a spoken mock interview: every word you write is read aloud.

How you speak:
- Like a real person across the table: plain, natural spoken English. Contractions are fine.
- At most two short sentences, under 30 words in total.
- No quotation marks, no markdown, no lists, no emojis.
- Never say "good start", "great answer" or similar praise. Never teach, never answer for them, never give feedback.

${MOODS[o.mood]}`
}

export function followUpMessages(o: PersonaOptions, question: string, answer: string, note: string): ChatMessage[] {
  const who = o.candidateName ?? 'The candidate'
  return [
    { role: 'user', content: `${persona(o)}\n\n${who} has just sat down. Ask your first question.` },
    { role: 'assistant', content: question },
    {
      role: 'user',
      content: `${answer}\n\n[Note for ${o.interviewer}, not said aloud: ${note} Refer to one detail they said. One question, under 30 words.]`,
    },
  ]
}

import type { GemmaClient } from '../gemma/GemmaClient'
import { angleNote } from './angles'
import type { WriteRequest } from './engine'
import { guardFollowUp } from './guard'
import { followUpMessages, type PersonaOptions } from './prompts'

// If Gemma has not answered by then, the written line is spoken instead: a
// long silence after an answer feels worse than a plainer question. Replies
// took 1.0 to 1.6 s in the evals.
const WRITE_TIMEOUT_MS = 6000

// Gemma words the follow-up the rules chose; the guard decides whether it can
// be spoken. Null means "use the written line".
export function makeWriter(gemma: GemmaClient, persona: PersonaOptions) {
  return async (req: WriteRequest): Promise<string | null> => {
    const messages = followUpMessages(persona, req.question.question, req.answer, angleNote(req.angle))
    let timer: ReturnType<typeof setTimeout> | undefined
    const timeout = new Promise<null>((resolve) => {
      timer = setTimeout(() => {
        gemma.stop()
        resolve(null)
      }, WRITE_TIMEOUT_MS)
    })
    try {
      const reply = await Promise.race([gemma.generate(messages, { maxNewTokens: 60 }), timeout])
      if (!reply || reply.stopped) return null
      return guardFollowUp(reply.text, req.question.question, req.answer)
    } finally {
      clearTimeout(timer)
    }
  }
}

