import { BANK, type Level, type Round, type Track } from './bank'
import type { Mood } from './lines'

// What the candidate chooses on the setup screen (TASKS.md 4.1).

export type InterviewerId = 'ananya' | 'aarav'

// The two interviewers: the package's avatar preset and a Kokoro voice each.
export const INTERVIEWERS: Record<InterviewerId, { name: string; avatar: 'ananya' | 'aarav'; voice: string }> = {
  ananya: { name: 'Ananya', avatar: 'ananya', voice: 'af_heart' },
  aarav: { name: 'Aarav', avatar: 'aarav', voice: 'am_michael' },
}

// System design is parked (PLAN.md), so it is not offered yet.
export type RoundChoice = Exclude<Round, 'system-design'> | 'full'

export type InterviewSettings = {
  round: RoundChoice
  track: Track
  level: Level
  // Questions in a single round; a full loop is always 5.
  count: number
  // Target length of one answer, for the timer and the report.
  answerMinutes: number
  interviewer: InterviewerId
  mood: Mood
  candidateName: string
}

export const DEFAULT_SETTINGS: InterviewSettings = {
  round: 'full',
  track: 'frontend',
  level: 'junior',
  count: 4,
  answerMinutes: 2,
  interviewer: 'ananya',
  mood: 'friendly',
  candidateName: '',
}

export const FULL_LOOP_COUNT = 5

// How many questions the bank has for this round, track and level.
export function availableCount(round: Exclude<RoundChoice, 'full'>, track: Track, level: Level): number {
  return BANK.filter(
    (q) => q.round === round && q.levels.includes(level) && (q.tracks.includes('any') || q.tracks.includes(track)),
  ).length
}

// Keeps a choice valid when another one changes (e.g. fewer questions exist
// for an intern backend technical round).
export function normalise(s: InterviewSettings): InterviewSettings {
  if (s.round === 'full') return s
  const max = Math.min(5, availableCount(s.round, s.track, s.level))
  return s.count > max ? { ...s, count: max } : s
}

import { DEFAULT_SETTINGS, normalise, type InterviewerId, type InterviewSettings } from '../interview/settings'

// App-level state: which screen is showing and what the candidate chose.
// Screens are switched here rather than by URL; there is nothing to link to
// inside an interview.

export type Mode = 'light' | 'heavy'
// How the interviewer appears. Same interview either way; only the display
// changes. 'video' shows the 3D avatar, 'phone' is voice only.
export type Display = 'video' | 'phone'
export type Screen = 'home' | 'setup' | 'interview' | 'report'

export type AppState = {
  screen: Screen
  mode: Mode | null
  // Null until picked on the setup screen. Picking it (with the interviewer,
  // whose avatar and voice load with it) starts loading the models, and it
  // cannot change after that (UX.md: downloads).
  display: Display | null
  settings: InterviewSettings
}

export type AppAction =
  | { type: 'chooseMode'; mode: Mode }
  | { type: 'chooseDisplay'; display: Display; interviewer: InterviewerId }
  | { type: 'updateSettings'; patch: Partial<InterviewSettings> }
  | { type: 'startInterview' }
  | { type: 'finishInterview' }
  | { type: 'practiceAgain' }
  | { type: 'goHome' }

export const initialState: AppState = { screen: 'home', mode: null, display: null, settings: DEFAULT_SETTINGS }

export function appReducer(state: AppState, action: AppAction): AppState {
  switch (action.type) {
    case 'chooseMode':
      return { ...state, mode: action.mode, display: null, screen: 'setup' }
    case 'chooseDisplay':
      return state.display
        ? state
        : { ...state, display: action.display, settings: { ...state.settings, interviewer: action.interviewer } }
    case 'updateSettings': {
      // The interviewer is locked once the models start loading.
      const { interviewer: _locked, ...patch } = action.patch
      const next = state.display ? patch : action.patch
      return { ...state, settings: normalise({ ...state.settings, ...next }) }
    }
    case 'startInterview':
      return state.mode && state.display ? { ...state, screen: 'interview' } : state
    case 'finishInterview':
      return { ...state, screen: 'report' }
    case 'practiceAgain':
      return { ...state, display: null, screen: 'setup' }
    case 'goHome':
      return { ...state, display: null, screen: 'home' }
  }
}

// The voice engine (react-ai-voice-avatar) owns its workers and kills them on
// unmount, so it is mounted once, from the display choice until the interview
// ends, and the screens change around it.
export function isEngineMounted(state: AppState): state is AppState & { display: Display; mode: Mode } {
  return (
    state.display !== null &&
    state.mode !== null &&
    (state.screen === 'setup' || state.screen === 'interview')
  )
}

