import { useEffect, useState } from 'react'

// How long the current answer has run against the candidate's target (UX.md:
// interview screen). Amber from 80% of the target, red past it. Counts from
// their first words, so thinking before speaking is not on the clock.
const fmt = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

export function AnswerTimer({ startedAt, targetMinutes, paused }: { startedAt: number | null; targetMinutes: number; paused: boolean }) {
  const [now, setNow] = useState(() => Date.now())

  useEffect(() => {
    if (startedAt === null || paused) return
    const id = setInterval(() => setNow(Date.now()), 250)
    return () => clearInterval(id)
  }, [startedAt, paused])

  const target = targetMinutes * 60_000
  const elapsed = startedAt === null ? 0 : now - startedAt
  const state = elapsed > target ? 'over' : elapsed >= target * 0.8 ? 'near' : 'ok'
  const fill = Math.min(1, elapsed / target)

  return (
    <div className={`answer-timer timer-${state}`}>
      <span className="timer-text">
        {startedAt === null ? `Target ${fmt(target)}` : `${fmt(elapsed)} / ${fmt(target)}`}
      </span>
      <span className="timer-bar" aria-hidden="true">
        <span style={{ width: `${fill * 100}%` }} />
      </span>
      {/* Announced once, not every second. */}
      <span className="sr-only" aria-live="polite">
        {state === 'over' ? `Past your ${targetMinutes} minute target.` : ''}
      </span>
    </div>
  )
}

import type { QuestionOutcome } from '../interview/engine'

// One dot per question: answered, skipped (or left in silence / "I don't
// know"), the current one, and those still to come.
export function ProgressDots({ total, index, outcomes }: { total: number; index: number; outcomes: QuestionOutcome[] }) {
  if (total === 0) return null
  const label = index >= 0 && index < total ? `Question ${index + 1} of ${total}` : `${total} questions`
  return (
    <ol className="dots" aria-label={label}>
      {Array.from({ length: total }, (_, i) => {
        const state =
          i === index ? 'current' : i < index ? (outcomes[i] === 'answered' ? 'done' : 'skipped') : 'todo'
        const words = { current: 'current', done: 'answered', skipped: 'skipped', todo: 'not yet asked' }[state]
        return (
          <li key={i} className={`dot dot-${state}`}>
            <span className="sr-only">
              Question {i + 1}, {words}
            </span>
          </li>
        )
      })}
    </ol>
  )
}

import { useEffect, useRef } from 'react'
import { usePrefersReducedMotion } from '../app/usePrefersReducedMotion'
import { useInterview } from '../interview/session'
import { getAudioLevel, useVoice } from '../voice/voiceStore'

export type OrbState = 'loading' | 'listening' | 'speaking' | 'thinking' | 'paused'

// The phone screen's interviewer (UX.md: look and feel): an orb that glows
// with whoever holds the floor, the candidate's voice while listening and the
// interviewer's while speaking, with a slow pulse while thinking. Only
// transform and opacity change per frame, so it stays light on a GPU that is
// busy with the models. Under reduced motion it holds still and only its
// brightness says the state.
export function Orb({ label }: { label: string }) {
  const voice = useVoice()
  const interview = useInterview()
  const reducedMotion = usePrefersReducedMotion()
  const ref = useRef<HTMLDivElement>(null)

  const state: OrbState = interview?.paused
    ? 'paused'
    : voice.status === 'loading'
      ? 'loading'
      : interview?.busy || voice.status === 'thinking'
        ? 'thinking'
        : voice.status === 'speaking'
          ? 'speaking'
          : 'listening'

  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (reducedMotion) {
      el.style.setProperty('--level', '0')
      return
    }
    let smooth = 0
    let frame = 0
    const tick = () => {
      const { level, source } = getAudioLevel()
      const wanted = source === 'idle' ? 0 : Math.min(1, level * 1.8)
      smooth += (wanted - smooth) * 0.2
      el.style.setProperty('--level', smooth.toFixed(3))
      frame = requestAnimationFrame(tick)
    }
    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
  }, [reducedMotion])

  return (
    <div className="orb-wrap">
      <div ref={ref} className={`orb orb-${state}`} aria-hidden="true">
        <span className="orb-glow" />
        <span className="orb-core" />
      </div>
      <p className="orb-label">{label}</p>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import type { Display } from '../app/state'
import { AnswerTimer } from '../components/AnswerTimer'
import { ProgressDots } from '../components/ProgressDots'
import { ScreenFrame } from '../components/ScreenFrame'
import type { ExchangeKind, PauseReason } from '../interview/engine'
import { interview, startInterview, useInterview } from '../interview/session'
import type { InterviewSettings } from '../interview/settings'
import { useVoice, type VoiceStatus } from '../voice/voiceStore'

// One clear state, in words (UX.md: interview screen). 'idle' means the mic is
// open and waiting for speech, which to the candidate is listening too.
const STATE_LABEL: Record<VoiceStatus, string> = {
  loading: 'Getting ready',
  idle: 'Listening',
  listening: 'Listening',
  thinking: 'Thinking',
  speaking: 'Speaking',
}

const PAUSED: Record<PauseReason, string> = {
  asked: "Paused. Say I'm ready, or press Resume, when you want to carry on.",
  button: "Paused. Say I'm ready, or press Resume, when you want to carry on.",
  hidden: 'Paused because the tab was in the background. Press Resume to carry on.',
  mic: 'Paused because the microphone stopped. Reconnect it, then press Resume.',
}

// Answers that count against the target length (not small talk or the
// candidate's own questions).
const TIMED: ExchangeKind[] = ['question', 'follow-up', 'probe', 'clarification']

// The interview room (TASKS.md 4.2). The avatar or the phone-screen orb is
// the voice engine's stage, which App keeps mounted beside this screen.
export function Interview({
  display,
  settings,
  onEnd,
}: {
  display: Display
  settings: InterviewSettings
  onEnd: () => void
}) {
  const voice = useVoice()
  const state = useInterview()
  const started = useRef(false)
  const [captions, setCaptions] = useState(true)

  useEffect(() => {
    if (started.current) return
    started.current = true
    startInterview(settings)
  }, [settings])

  const finished = state?.phase === 'done'
  // The engine is busy while Gemma words a follow-up; the package is idle then.
  const label = finished ? 'Finished' : state?.paused ? 'Paused' : state?.busy ? 'Thinking' : STATE_LABEL[voice.status]
  const timed = !finished && !!state?.currentKind && TIMED.includes(state.currentKind)

  return (
    <ScreenFrame title={display === 'video' ? 'Video interview' : 'Phone screen'}>
      <div className="room-bar">
        <span className={`state state-${label.toLowerCase().replace(' ', '-')}`} role="status">
          {label}
        </span>
        {state && (
          <ProgressDots
            total={state.total}
            index={finished ? state.total : state.questionIndex}
            outcomes={state.records.map((r) => r.outcome)}
          />
        )}
        {timed && (
          <AnswerTimer startedAt={state.answerStartedAt} targetMinutes={settings.answerMinutes} paused={!!state.paused} />
        )}
      </div>

      {voice.micError && (
        <div className="notice">
          <p className="notice-title">The microphone isn't available</p>
          <p>
            Allow microphone access for this page (the icon in the address bar), check that a
            microphone is connected, then press Resume. ({voice.micError})
          </p>
        </div>
      )}

      {state?.paused && !voice.micError && (
        <div className="notice">
          <p>{PAUSED[state.paused]}</p>
        </div>
      )}

      {state?.notes.map((note) => (
        <p key={note} className="muted">
          {note}
        </p>
      ))}

      <section className="question-card" aria-labelledby="question-title">
        <h2 id="question-title" className="label">
          {state?.question ? `Question ${state.questionIndex + 1}` : finished ? 'All done' : 'Warming up'}
        </h2>
        <p className="question">
          {state?.question?.question ?? (finished ? 'Thanks for practising. Your report is ready.' : 'A quick hello before the first question.')}
        </p>
      </section>

      {captions && (
        <section className="captions" aria-label="Captions">
          <div>
            <h3 className="label">Interviewer</h3>
            <p className="said">{state?.interviewerLine}</p>
          </div>
          <div>
            <h3 className="label">What I heard</h3>
            <p className={state?.currentAnswer ? 'heard' : 'heard placeholder'} aria-live="polite">
              {state?.currentAnswer || 'Your words appear here as you speak. Take your time: pauses are fine.'}
            </p>
          </div>
        </section>
      )}

      <div className="actions interview-controls">
        {finished ? (
          <button type="button" className="primary" onClick={onEnd}>
            See your report
          </button>
        ) : (
          <>
            <button
              type="button"
              className="primary"
              onClick={interview.done}
              disabled={!state?.currentAnswer || !!state?.paused}
            >
              I'm done
            </button>
            {state?.paused ? (
              <button type="button" onClick={interview.resume}>
                Resume
              </button>
            ) : (
              <button type="button" onClick={interview.pause}>
                Pause
              </button>
            )}
            <button type="button" onClick={interview.repeat}>
              Repeat question
            </button>
            <button type="button" onClick={interview.skip} disabled={!state?.question}>
              Skip
            </button>
            <button
              type="button"
              onClick={() => {
                interview.end()
                onEnd()
              }}
            >
              End interview
            </button>
          </>
        )}
        <button type="button" className="quiet" aria-pressed={captions} onClick={() => setCaptions((c) => !c)}>
          {captions ? 'Hide captions' : 'Show captions'}
        </button>
      </div>
    </ScreenFrame>
  )
}

import { useEffect, useRef, useState } from 'react'
import type { Display } from '../app/state'
import { AnswerTimer } from '../components/AnswerTimer'
