import type { Display, Mode } from '../app/state'
import type { EngineSnapshot, QuestionRecord } from '../interview/engine'
import type { InterviewSettings } from '../interview/settings'
import { measureInterview, type InterviewMeasures } from './measure'

// One finished interview, as the report and the self-review use it, and as it
// is saved on the device (store.ts). It keeps the engine's records as they
// were, questions included, so an old report still reads the same after the
// bank changes. The measured numbers are not saved: they are worked out from
// the records each time (measure.ts, instant).

// How an answer felt to the candidate, asked before they see the points.
export type Feel = 'good' | 'okay' | 'rough'

// The candidate's own mark for one strong-answer point.
export type Mark = 'covered' | 'partly' | 'missed'

// One answer's self-review: the feel, then a mark per point (same order as the
// question's `points`; null until marked).
export type AnswerReview = { feel: Feel | null; marks: (Mark | null)[] }

// 'skipped': the candidate went straight to the numbers.
export type ReviewState = 'not-started' | 'in-progress' | 'done' | 'skipped'

export type InterviewReport = {
  id: string
  version: 1
  createdAt: number
  mode: Mode
  display: Display
  settings: InterviewSettings
  records: QuestionRecord[]
  // Things the interview noticed about itself, e.g. Gemma failing.
  notes: string[]
  // By question id.
  review: Record<string, AnswerReview>
  reviewState: ReviewState
}

export function createReport(
  snapshot: EngineSnapshot,
  settings: InterviewSettings,
  mode: Mode,
  display: Display,
  now = Date.now(),
): InterviewReport {
  return {
    id: `interview-${now}`,
    version: 1,
    createdAt: now,
    mode,
    display,
    settings,
    // A copy: the live engine keeps no reference into a saved report.
    records: structuredClone(snapshot.records),
    notes: [...snapshot.notes],
    review: {},
    reviewState: 'not-started',
  }
}

// The answers the candidate reviews, in order: answered ones whose question
// has strong-answer points. Skipped, silent and empty answers are shown in the
// report as such, not reviewed.
export function reviewQueue(report: InterviewReport, m: InterviewMeasures = measures(report)): QuestionRecord[] {
  return report.records.filter(
    (r, i) => m.questions[i].status === 'answered' && (r.question.points?.length ?? 0) > 0,
  )
}

export function measures(report: InterviewReport): InterviewMeasures {
  return measureInterview(report.records, report.settings.answerMinutes * 60_000)
}

export function reviewFor(report: InterviewReport, record: QuestionRecord): AnswerReview {
  return (
    report.review[record.question.id] ?? {
      feel: null,
      marks: (record.question.points ?? []).map(() => null),
    }
  )
}

// Updates return a new report (React state, and saved as a whole).

export function setFeel(report: InterviewReport, record: QuestionRecord, feel: Feel): InterviewReport {
  const current = reviewFor(report, record)
  return withReview(report, record, { ...current, feel })
}

export function setMark(report: InterviewReport, record: QuestionRecord, point: number, mark: Mark): InterviewReport {
  const current = reviewFor(report, record)
  const marks = current.marks.map((m, i) => (i === point ? mark : m))
  return withReview(report, record, { ...current, marks })
}

export function setReviewState(report: InterviewReport, reviewState: ReviewState): InterviewReport {
  return { ...report, reviewState }
}

function withReview(report: InterviewReport, record: QuestionRecord, review: AnswerReview): InterviewReport {
  return {
    ...report,
    review: { ...report.review, [record.question.id]: review },
    reviewState: report.reviewState === 'not-started' ? 'in-progress' : report.reviewState,
  }
}

import { useEffect, useState } from 'react'
import type { InterviewReport } from './report'

// Finished interviews, kept on this device in IndexedDB so the report and the
// candidate's marks survive a reload. Nothing is sent anywhere.
//
// Every report is also kept in memory, so the report screen has it at once
// and still works where IndexedDB is unavailable (a private window, blocked
// storage); then it lasts until the tab closes, and `saveReport` says so.

const DB_NAME = 'interview-room'
const DB_VERSION = 1
const STORE = 'reports'

const memory = new Map<string, InterviewReport>()
let dbPromise: Promise<IDBDatabase> | null = null

function openDb(): Promise<IDBDatabase> {
  dbPromise ??= new Promise<IDBDatabase>((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION)
    req.onupgradeneeded = () => {
      const db = req.result
      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE, { keyPath: 'id' })
    }
    req.onsuccess = () => resolve(req.result)
    req.onerror = () => reject(req.error)
    req.onblocked = () => reject(new Error('IndexedDB is blocked by another tab'))
  }).catch((e: unknown) => {
    dbPromise = null
    throw e
  })
  return dbPromise
}

function run<T>(mode: IDBTransactionMode, fn: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return openDb().then(
    (db) =>
      new Promise<T>((resolve, reject) => {
        const tx = db.transaction(STORE, mode)
        const req = fn(tx.objectStore(STORE))
        tx.oncomplete = () => resolve(req.result)
        tx.onerror = () => reject(tx.error)
        tx.onabort = () => reject(tx.error)
      }),
  )
}

// True when saved on the device; false when it is only in memory.
export async function saveReport(report: InterviewReport): Promise<boolean> {
  memory.set(report.id, report)
  notify(report.id)
  try {
    await run('readwrite', (s) => s.put(report))
    return true
  } catch (e) {
    console.warn('[report] could not save on this device:', e)
    return false
  }
}

export async function getReport(id: string): Promise<InterviewReport | null> {
  const kept = memory.get(id)
  if (kept) return kept
  try {
    const found = (await run<InterviewReport | undefined>('readonly', (s) => s.get(id))) ?? null
    if (found) memory.set(id, found)
    return found
  } catch {
    return null
  }
}

// Newest first.
export async function listReports(): Promise<InterviewReport[]> {
  let saved: InterviewReport[] = []
  try {
    saved = await run<InterviewReport[]>('readonly', (s) => s.getAll())
  } catch {
    // Only what is in memory.
  }
  const byId = new Map(saved.map((r) => [r.id, r]))
  memory.forEach((r, id) => byId.set(id, r))
  return [...byId.values()].sort((a, b) => b.createdAt - a.createdAt)
}

// --- For React: the report with this id, kept up to date as it is saved.

const listeners = new Set<(id: string) => void>()

function notify(id: string) {
  listeners.forEach((l) => l(id))
}

export function useReport(id: string | null): { report: InterviewReport | null; loading: boolean } {
  const [state, setState] = useState<{ id: string | null; report: InterviewReport | null; loading: boolean }>({
    id,
    report: id ? (memory.get(id) ?? null) : null,
    loading: !!id && !memory.has(id),
  })
  if (state.id !== id) {
    setState({ id, report: id ? (memory.get(id) ?? null) : null, loading: !!id && !memory.has(id) })
  }

  useEffect(() => {
    if (!id) return
    let live = true
    if (!memory.has(id)) {
      void getReport(id).then((report) => live && setState({ id, report, loading: false }))
    }
    const onSaved = (saved: string) => {
      if (saved === id && live) setState({ id, report: memory.get(id) ?? null, loading: false })
    }
    listeners.add(onSaved)
    return () => {
      live = false
      listeners.delete(onSaved)
    }
  }, [id])

  return { report: state.report, loading: state.loading }
}

import { BANK } from '../interview/bank'
import { InterviewEngine, LONG_PAUSE_MS, type EngineSnapshot } from '../interview/engine'
import { DEFAULT_SETTINGS, INTERVIEWERS, type InterviewSettings } from '../interview/settings'
import { wordCount } from '../interview/text'

// Dev only: a whole interview run through the real engine with a fake clock,
// fed the same signals the voice sends (interviewer finished, speech ended,
// transcript), so the report gets exactly what a real run records. No models.
//
// The candidate's answers are written to exercise the report: fillers, "we"
// far more than "I", numbers, a long pause, an answer past the target time, a
// skipped question, a follow-up reply, and talking over the interviewer.

export const FAKE_SETTINGS: InterviewSettings = { ...DEFAULT_SETTINGS, round: 'full', track: 'frontend', answerMinutes: 1 }

const DETECTOR_WAIT_MS = 1400
const WHISPER_MS = 600

type Stretch = { text: string; wpm?: number; gapMs?: number }

export function fakeInterview(startAt = Date.now()): EngineSnapshot {
  let now = startAt
  let timers: { fn: () => void; at: number; id: number }[] = []
  let nextId = 1
  let snapshot: EngineSnapshot | null = null
  const spoken: string[] = []

  const questions = ['b-improved', 'fe-useeffect', 'b-feedback', 'h-leaving'].map((id) => BANK.find((q) => q.id === id)!)
  const engine = new InterviewEngine(
    {
      questions,
      track: FAKE_SETTINGS.track,
      level: FAKE_SETTINGS.level,
      interviewer: INTERVIEWERS[FAKE_SETTINGS.interviewer].name,
      mood: FAKE_SETTINGS.mood,
    },
    {
      speak: (text) => spoken.push(text),
      now: () => now,
      setTimer: (fn, ms) => {
        const t = { fn, at: now + ms, id: nextId++ }
        timers.push(t)
        return t.id
      },
      clearTimer: (id) => (timers = timers.filter((t) => t.id !== id)),
      onChange: (s) => (snapshot = s),
    },
  )

  const advance = (ms: number) => {
    const until = now + ms
    for (;;) {
      const due = timers.filter((t) => t.at <= until).sort((a, b) => a.at - b.at)[0]
      if (!due) break
      now = due.at
      timers = timers.filter((t) => t !== due)
      due.fn()
    }
    now = until
  }
  // The interviewer's line plays, roughly at speaking pace.
  const interviewerSpeaks = () => {
    advance(Math.max(1500, wordCount(spoken.at(-1) ?? '') * 380))
    engine.interviewerFinished()
  }
  // The candidate's answer: stretches of speech with gaps between them.
  const answer = (firstWordAfterMs: number, stretches: Stretch[]) => {
    advance(firstWordAfterMs)
    stretches.forEach((s, i) => {
      if (i > 0) {
        // The previous transcript arrived DETECTOR_WAIT_MS + WHISPER_MS after
        // the speech ended; the rest of the gap passes before they talk again.
        advance(Math.max(0, (s.gapMs ?? 1600) - DETECTOR_WAIT_MS - WHISPER_MS))
      }
      engine.userStartedSpeaking()
      const speechMs = Math.round((wordCount(s.text) / (s.wpm ?? 140)) * 60_000)
      advance(speechMs)
      engine.speechEnded(now)
      advance(DETECTOR_WAIT_MS + WHISPER_MS)
      engine.heard(s.text, speechMs)
    })
    // The long pause ends the answer, and the next line plays.
    advance(LONG_PAUSE_MS.normal)
    interviewerSpeaks()
  }

  engine.start()
  interviewerSpeaks()
  answer(900, [{ text: "Hi, I'm doing well, thanks. A bit nervous but excited." }])

  // 1. b-improved: "we" far more than "I", fillers, numbers, a long pause, past
  //    the 1 minute target.
  answer(2600, [
    {
      text: 'So, basically, at my last internship we had this dashboard that was, like, really slow. We noticed that the main page took about 9 seconds to load on a normal laptop, and our support team kept getting complaints from customers about it.',
      wpm: 150,
    },
    {
      text: 'We looked into it as a team, and, you know, we found that the page was fetching the same data four times and we were also rendering a huge table with all the rows at once. So we decided to add caching with React Query and we virtualised the table.',
      wpm: 145,
      gapMs: 4200,
    },
    {
      text: 'We also kind of split the bundle so the charts loaded later. After that, the page loaded in around 2 seconds, and the complaints basically stopped. I think it was a good project for our team, and we learned a lot about performance.',
      wpm: 135,
      gapMs: 1800,
    },
  ])
  // The follow-up (written, no Gemma here) and a short reply.
  answer(1800, [
    {
      text: 'I mean, I was the one who profiled it in the React Profiler and found the repeated fetches. I wrote the caching layer myself.',
      wpm: 155,
    },
  ])

  // 2. fe-useeffect: a fair technical answer, within time; misses cleanup.
  answer(1400, [
    {
      text: 'useEffect lets you run side effects after React renders the component. For example fetching data from an API, or setting up a subscription or a timer.',
      wpm: 140,
    },
    {
      text: 'The dependency array controls when it runs again. If you pass an empty array it only runs once after the first render, and if you leave it out it runs after every render.',
      wpm: 140,
      gapMs: 2200,
    },
  ])
  answer(3800, [{ text: "If it unmounts during a fetch, I think you'd get a warning. You can use an abort controller in the cleanup.", wpm: 125 }])

  // 3. b-feedback: skipped.
  advance(2500)
  engine.skip()
  interviewerSpeaks()

  // 4. h-leaving: starts before the interviewer finishes (talks over the end
  //    of the question), short and a little fast.
  advance(-1) // no-op guard: keep the clock monotonic
  engine.userStartedSpeaking()
  {
    const text =
      "I'm looking for a role where I can own features end to end and work on a product with real users. My current team is great and I've learned a lot there, but the scope is quite narrow."
    const speechMs = Math.round((wordCount(text) / 175) * 60_000)
    // The question's end is recorded just after they started.
    advance(400)
    engine.interviewerFinished()
    advance(speechMs - 400)
    engine.speechEnded(now)
    advance(DETECTOR_WAIT_MS + WHISPER_MS)
    engine.heard(text, speechMs)
    advance(LONG_PAUSE_MS.normal)
    interviewerSpeaks()
  }
  answer(2000, [{ text: 'More ownership, and working closely with designers and users.', wpm: 140 }])

  // Candidate questions, then the closing line.
  answer(1500, [{ text: 'What does a typical week look like for someone joining the team?' }])

  if (!snapshot) throw new Error('fake interview produced no snapshot')
  return snapshot
}

