import { lazy, Suspense } from 'react'
import { ScreenFrame } from '../components/ScreenFrame'
import { useReport } from '../report/store'

const SessionLog = import.meta.env.DEV ? lazy(() => import('../dev/SessionLog')) : null

// Placeholder until the self-review and report steps fill it in: specific to
// what they said, quoting their answers, measured numbers only (UX.md:
// report). Reads the saved report, so it survives a reload. Dev builds show
// the raw session log and the measured numbers for checking a run.
export function Report({
  reportId,
  onPracticeAgain,
  onHome,
}: {
  reportId: string | null
  onPracticeAgain: () => void
  onHome: () => void
}) {
  const { report, loading } = useReport(reportId)
  return (
    <ScreenFrame title="Your interview">
      <section aria-labelledby="answers-title" className="panel">
        <h2 id="answers-title">Your answers</h2>
        <p className="placeholder">
          {loading
            ? 'Loading your report…'
            : report
              ? `${report.records.length} questions. Each answer, in your words, with what was measured.`
              : 'This report could not be found on this device.'}
        </p>
      </section>

      {SessionLog && report && (
        <Suspense fallback={null}>
          <SessionLog report={report} />
        </Suspense>
      )}

      <div className="actions">
        <button type="button" onClick={onHome}>
          Home
        </button>
        <button type="button" className="primary" onClick={onPracticeAgain}>
          Practice again
        </button>
      </div>
    </ScreenFrame>
  )
}

import { useState } from 'react'
import type { Exchange } from '../interview/engine'
import { measures, type InterviewReport } from '../report/report'

// Dev only: everything the engine recorded in the interview, and what the
// report measured from it, as JSON to copy and paste back when something
// breaks (TASKS.md 4.3). Times are seconds from the start of each question.
function seconds(ms: number | undefined, start: number) {
  return ms === undefined ? undefined : +((ms - start) / 1000).toFixed(1)
}

function exchange(e: Exchange, start: number) {
  return {
    kind: e.kind,
    said: e.said,
    angle: e.angle?.kind,
    byGemma: e.byGemma,
    asked: seconds(e.askedAt, start),
    askedEnded: seconds(e.askedEndedAt, start),
    answer: e.parts.map((p) => ({
      t: seconds(p.at, start),
      from: seconds(p.startedAt, start),
      to: seconds(p.endedAt, start),
      speechMs: p.speechMs,
      text: p.text,
    })),
  }
}

function sessionLog(r: InterviewReport) {
  return {
    id: r.id,
    mode: r.mode,
    display: r.display,
    answerMinutes: r.settings.answerMinutes,
    notes: r.notes,
    smallTalk: r.smallTalk && exchange(r.smallTalk, r.smallTalk.askedAt),
    questions: r.records.map((q) => ({
      id: q.question.id,
      outcome: q.outcome,
      seconds: q.endedAt ? +((q.endedAt - q.startedAt) / 1000).toFixed(1) : null,
      exchanges: q.exchanges.map((e) => exchange(e, q.startedAt)),
    })),
    candidateQuestions: r.candidateQuestions && exchange(r.candidateQuestions, r.candidateQuestions.askedAt),
    review: r.review,
    reviewState: r.reviewState,
  }
}

// The measured numbers, shortened: offsets replaced by the words they point at.
function measured(r: InterviewReport) {
  const m = measures(r)
  const one = (x: NonNullable<(typeof m.questions)[number]['answer']>) => ({
    words: x.words,
    fillers: x.fillers.map((f) => f.text),
    pronouns: x.pronouns,
    numbers: x.numbers.map((n) => n.text),
    timing: { ...x.timing, longGaps: x.timing.longGaps.map((g) => g.ms) },
  })
  return {
    ...m,
    questions: m.questions.map((q) => ({
      id: q.questionId,
      status: q.status,
      answer: q.answer && one(q.answer),
      overTargetMs: q.overTargetMs,
      overTargetFrom: q.answer && q.overTargetAt !== null ? `${q.answer.text.slice(q.overTargetAt, q.overTargetAt + 40)}…` : null,
      followUp: q.followUp && { said: q.followUp.said, reply: q.followUp.reply && one(q.followUp.reply) },
    })),
  }
}

function CopyBlock({ title, text }: { title: string; text: string }) {
  const [copied, setCopied] = useState('')
  return (
    <details className="panel session-log">
      <summary>{title} (dev only)</summary>
      <div className="actions" style={{ justifyContent: 'flex-start' }}>
        <button
          type="button"
          onClick={() =>
            navigator.clipboard.writeText(text).then(
              () => setCopied('Copied.'),
              () => setCopied('Copy failed: select the text below instead.'),
            )
          }
        >
          Copy
        </button>
        <span className="muted" role="status">
          {copied}
        </span>
      </div>
      <pre>{text}</pre>
    </details>
  )
}

export default function SessionLog({ report }: { report: InterviewReport }) {
  return (
    <>
      <CopyBlock title="Session log" text={JSON.stringify(sessionLog(report), null, 2)} />
      <CopyBlock title="Measured" text={JSON.stringify(measured(report), null, 2)} />
    </>
  )
}

import { useEffect, useState } from 'react'
import { createReport } from '../report/report'
import { listReports, saveReport } from '../report/store'
import { Report } from '../screens/Report'
import { FAKE_SETTINGS, fakeInterview } from './fakeInterview'

// Dev only (`?dev=report`): the report screen with a fake interview run
// through the real engine (fakeInterview.ts), saved in IndexedDB like a real
// one. Opens the newest saved report, so a reload shows the same one (and the
// marks on it); "New fake interview" makes another.
export default function ReportPreview() {
  const [ids, setIds] = useState<{ id: string; label: string }[]>([])
  const [id, setId] = useState<string | null>(null)
  const [saved, setSaved] = useState<boolean | null>(null)

  const refresh = async () => {
    const all = await listReports()
    setIds(all.map((r) => ({ id: r.id, label: `${new Date(r.createdAt).toLocaleString()} · ${r.records.length} questions` })))
    return all
  }

  const makeFake = async () => {
    const report = createReport(fakeInterview(), FAKE_SETTINGS, 'light', 'phone')
    setSaved(await saveReport(report))
    setId(report.id)
    await refresh()
  }

  useEffect(() => {
    void refresh().then((all) => {
      if (all[0]) setId(all[0].id)
      else void makeFake()
    })
  }, [])

  return (
    <>
      <div className="panel">
        <div className="actions" style={{ justifyContent: 'flex-start' }}>
          <button type="button" onClick={() => void makeFake()}>
            New fake interview
          </button>
          <select value={id ?? ''} onChange={(e) => setId(e.target.value)} aria-label="Saved reports">
            {ids.map((r) => (
              <option key={r.id} value={r.id}>
                {r.label}
              </option>
            ))}
          </select>
          <span className="muted" role="status">
            {saved === null ? '' : saved ? 'Saved in IndexedDB.' : 'Not saved: IndexedDB unavailable, kept in memory.'}
          </span>
        </div>
      </div>
      <Report reportId={id} onPracticeAgain={() => void makeFake()} onHome={() => location.assign('/')} />
    </>
  )
}
